def choose_move(observation):
    def pt(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return 0, 0

    def points(keys):
        out = []
        for k in keys:
            vals = observation.get(k, [])
            if isinstance(vals, dict):
                vals = vals.values()
            for p in vals if isinstance(vals, (list, tuple, set)) else []:
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    out.append((p[0], p[1]))
        return out

    def first_point(keys):
        pts = points(keys)
        return pts[0] if pts else None

    def bounded(nx, ny, w, h, obstacles):
        if w and (nx < 0 or nx >= w):
            return False
        if h and (ny < 0 or ny >= h):
            return False
        if (nx, ny) in obstacles:
            return False
        return True

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0

    sx, sy = pt(observation.get("self_position", observation.get("agent_position", (0, 0))))
    ox, oy = pt(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))))

    obstacles = set(points(("obstacles", "walls", "blocked", "rocks", "lava", "holes")))
    resources = points(("resources", "food", "pellets", "collectibles", "targets", "coins", "items"))
    territory_targets = points(("frontier", "border", "capture_points", "neutral", "unclaimed", "objective"))
    extras = points(("enemy_territory", "enemy_cells", "enemy_area", "visited", "trail", "path"))

    mode = "territory"
    if resources:
        mode = "resource"
    elif abs(sx - ox) + abs(sy - oy) <= 4 and not territory_targets:
        mode = "pursuit"

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    def nearest_dist(x, y, pts):
        if not pts:
            return 10**9
        best = 10**9
        for px, py in pts:
            d = abs(x - px) + abs(y - py)
            if d < best:
                best = d
        return best

    def score(dx, dy):
        nx, ny = sx + dx, sy + dy
        if not bounded(nx, ny, w, h, obstacles):
            return -10**9

        sd = abs(nx - ox) + abs(ny - oy)
        rd = nearest_dist(nx, ny, resources)
        td = nearest_dist(nx, ny, territory_targets)
        ed = nearest_dist(nx, ny, extras)

        s = 0

        if mode == "resource":
            s += 12 - 4 * rd
            s += 2 * sd
            if rd == 0:
                s += 20
            if sd <= 1:
                s -= 3
        elif mode == "pursuit":
            s += 8 * (4 - min(sd, 4))
            s -= 2 * nearest_dist(nx, ny, resources)
            if sd == 1:
                s += 6
        else:
            if territory_targets:
                s += 10 - 3 * td
            else:
                cx = (w - 1) / 2 if w else 0
                cy = (h - 1) / 2 if h else 0
                s += -abs(nx - cx) - abs(ny - cy)
            s += 2 * sd
            s += -min(ed, 6)

        if dx == 0 and dy == 0:
            s -= 1

        # mild preference for reducing crowding near opponent when in open space
        if sd <= 2:
            s += 1

        return s

    best = (0, 0)
    bests = -10**18
    for dx, dy in moves:
        s = score(dx, dy)
        if s > bests:
            bests = s
            best = (dx, dy)

    return [best[0], best[1]]

